mapper.select:
SELECT id, user_id, item_id, eaten_on, custom_note, review, rating, price
FROM records
WHERE id = #{id}

SELECT records.id, records.eaten_on, records.rating, items.item_name, items.category_id, shops.shop_name
FROM records
  JOIN items ON items.id = records.item_id
  JOIN shops ON shops.id = items.shop_id
WHERE records.user_id = #{userId}

  AND items.category_id = #{categoryId}


  AND shops.shop_kind_id = #{shopKindId}


  AND records.eaten_on >= #{eatenFrom}


  AND records.eaten_on <= #{eatenTo}


  AND (records.eaten_on < #{cursorEatenOn}
    OR (records.eaten_on = #{cursorEatenOn} AND records.id < #{cursorId}))

ORDER BY records.eaten_on DESC, records.id DESC
LIMIT #{limit}

SELECT record_id, photo_path, sort_order FROM record_photos WHERE record_id IN
#{recordId}
ORDER BY record_id, sort_order
